package net.mclorehub.character;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class CharacterSlotsTest {
    CharacterLoreTest f;@TempDir Path temp;
    @BeforeEach void setup()throws Exception {f=new CharacterLoreTest();f.setup();}
    CharacterBook.Sheet sheet(int cap,int loss,CharacterBook.Entry... entries){var s=f.sheet(entries);return new CharacterBook.Sheet(s.id(),s.name(),s.notes(),false,s.entries(),s.facts(),s.history(),new SlotBudget(cap,loss,Map.of()));}
    CharacterBook.Sheet allocate(CharacterBook.Sheet s,CharacterBook.Entry e,int n){return new CharacterBook.Sheet(s.id(),s.name(),s.notes(),false,s.entries(),s.facts(),s.history(),s.budget().allocate(SlotBudget.key(e),n));}
    @Test void exactKnownCostsAndCapacity()throws Exception {var r=f.lore.slots(sheet(5,0,f.entry("kani"),f.entry("blood-magic")));assertEquals(3,r.minimum());assertEquals(3,r.maximum());assertFalse(r.overBudget());}
    @Test void unknownCapacityAndHistoryNeverBecomeZero()throws Exception {var r=f.lore.slots(sheet(-1,-1,f.entry("kani")));assertEquals(2,r.minimum());assertEquals(-1,r.maximum());assertEquals(-1,r.capacity());assertTrue(r.text().contains("history is not assumed complete"));}
    @Test void sourceTotalsDetectOverBudget()throws Exception {var r=f.lore.slots(sheet(5,0,f.entry("templar"),f.entry("necromancy")));assertEquals(6,r.minimum());assertTrue(r.overBudget());}
    @Test void duplicateBranchesShareOneDedication()throws Exception {var r=f.lore.slots(sheet(5,0,f.branch(f.entry("kani"),"Sun"),f.branch(f.entry("kani"),"Moon")));assertEquals(2,r.minimum());assertTrue(r.text().contains("grouped once"));}
    @Test void optionalSlotsRemainRangeUntilRecorded()throws Exception {var e=f.entry("air-evocation");var s=sheet(5,0,e);var r=f.lore.slots(s);assertEquals(1,r.minimum());assertEquals(2,r.maximum());assertEquals(2,f.lore.slots(allocate(s,e,2)).minimum());}
    @Test void allocationsCannotSilentlyUndercountKnownSourceCost()throws Exception {var e=f.entry("kani");var r=f.lore.slots(allocate(sheet(5,0,e),e,0));assertEquals(1,r.contradictions());assertEquals(2,r.minimum());}
    @Test void unknownManualEntriesCanHaveExplicitArithmetic()throws Exception {var e=new CharacterBook.Entry(UUID.randomUUID().toString(),CharacterBook.Kind.MAGIC,"Manual","","","",CharacterBook.RecordedStatus.PENDING,"","");var s=sheet(5,0,e);assertEquals(-1,f.lore.slots(s).maximum());assertEquals(2,f.lore.slots(allocate(s,e,2)).maximum());assertTrue(f.lore.slots(allocate(s,e,2)).text().contains("user-recorded allocation"));}
    @Test void lostNecromancyCountIsNotDoubledByRepeatedHistory()throws Exception {var s=sheet(5,3);var history=new ArrayList<CharacterBook.HistoryEvent>();for(int i=0;i<2;i++)history.add(new CharacterBook.HistoryEvent(UUID.randomUUID().toString(),"Lost","lotc:topic:249533",CharacterBook.EventType.DISCONNECTED,"",""));var r=f.lore.slots(new CharacterBook.Sheet(s.id(),s.name(),"",false,List.of(),s.facts(),history,s.budget()));assertEquals(3,r.minimum());assertEquals(3,r.lostMinimum());assertEquals(0,r.contradictions());}
    @Test void explicitZeroLostConflictsWithKnownDisconnection()throws Exception {var s=sheet(5,0);var h=new CharacterBook.HistoryEvent(UUID.randomUUID().toString(),"Lost","lotc:topic:249533",CharacterBook.EventType.DISCONNECTED,"","");var r=f.lore.slots(new CharacterBook.Sheet(s.id(),s.name(),"",false,List.of(),s.facts(),List.of(h),s.budget()));assertEquals(3,r.minimum());assertEquals(1,r.contradictions());}
    @Test void seerFeatHistoryDoesNotInventBondedLoss()throws Exception {var s=sheet(5,0);var h=new CharacterBook.HistoryEvent(UUID.randomUUID().toString(),"Seer feat","lotc:topic:211641",CharacterBook.EventType.DISCONNECTED,"","");assertEquals(0,f.lore.slots(new CharacterBook.Sheet(s.id(),s.name(),"",false,List.of(),s.facts(),List.of(h),s.budget())).minimum());}
    @Test void mysticTierChangesSourceRange()throws Exception {var e=f.entry("mysticism");assertEquals(1,f.lore.slotCost(e).minimum());var t2=new CharacterBook.Entry(e.id(),e.kind(),e.name(),"","T2","",e.status(),"",e.loreDocumentId());assertEquals(1,f.lore.slotCost(t2).maximum());var wight=new CharacterBook.Entry(e.id(),e.kind(),e.name(),"Wight","T5","",e.status(),"",e.loreDocumentId());assertEquals(3,f.lore.slotCost(wight).maximum());}
    @Test void voidstalkerCreditIsOnlyOneOptionalSlot()throws Exception {var air=f.entry("air-evocation");var s=sheet(5,0,air,f.entry("fire-evocation"),f.entry("transfiguration"),f.entry("voidal-translocation"),f.entry("blood-magic"),f.entry("voidstalking"));s=allocate(s,air,2);s=allocate(s,s.entries().get(1),1);var r=f.lore.slots(s);assertEquals(5,r.minimum());assertTrue(r.text().contains("one optional Voidal allocation credited"));}
    @Test void voidstalkerDoesNotPermitSixthPaidMagic()throws Exception {var r=f.lore.slots(sheet(6,0,f.entry("air-evocation"),f.entry("fire-evocation"),f.entry("water-evocation"),f.entry("earth-evocation"),f.entry("life-evocation"),f.entry("transfiguration"),f.entry("voidstalking")));assertTrue(r.contradictions()>0);assertTrue(r.text().contains("sixth paid magic"));}
    @Test void staleSourceCostsRemainUnknown()throws Exception {var lore=f.changed("lotc:topic:228968",d->f.change(d,d.body()+"changed",d.fingerprint(),d.status(),d.role()));assertEquals(-1,lore.slots(sheet(5,0,f.entry("kani"))).maximum());}
    @Test void budgetsSurviveAllOtherEditsAndPersistence()throws Exception {var b=CharacterBook.empty().create("First");String id=b.selectedId();var budget=new SlotBudget(5,1,Map.of());b=b.budget(id,budget).rename(id,"Renamed","").facts(id,CharacterFacts.unknown()).archive(id,true).archive(id,false).select(id);var e=f.entry("kani");b=b.putEntry(id,e).removeEntry(id,e.id());var store=new CharacterStore(temp.resolve("characters.json"));store.save(b,Optional.empty());assertEquals(budget,store.load().book().selected().orElseThrow().budget());}
    @Test void invalidBudgetsAreRejected(){assertThrows(IllegalArgumentException.class,()->new SlotBudget(-2,0,Map.of()));assertThrows(IllegalArgumentException.class,()->new SlotBudget(5,101,Map.of()));assertThrows(IllegalArgumentException.class,()->new SlotBudget(5,0,Map.of("../x",2)));}
    @Test void bardmasteryIncludesFullParentDedication()throws Exception{var r=f.lore.slots(sheet(5,0,f.entry("bardmancy"),f.entry("bardmastery")));assertEquals(3,r.minimum());assertEquals(3,r.maximum());}
    @Test void palmreadingPreservesLegacyThreeSlotCase()throws Exception{var e=f.entry("palmreading");assertFalse(f.lore.validAllocation(e,1));assertTrue(f.lore.validAllocation(e,3));assertEquals(3,f.lore.slots(allocate(sheet(5,0,e),e,3)).minimum());}
}
